<script setup>
import { computed, reactive, watch } from 'vue'
import { useRoute } from 'vue-router'
import { createAppNavigation } from '../../services/app-navigation.js'
import { routeAllowed } from '../../services/access.js'
import { prototypeAuth } from '../../services/prototype-runtime.js'
import { prototypeSection } from '../../services/prototype-data.js'
import WhiteLabelBrand from '../WhiteLabelBrand.vue'
const props=defineProps({visited:{type:Array,default:()=>[]}}),emit=defineEmits(['navigate'])
const route=useRoute(),expanded=reactive({home:false,whatsapp:route.path.includes('/whatsapp')})
watch(()=>route.path,path=>{if(path.includes('/whatsapp'))expanded.whatsapp=true})
const key=item=>item.to==='/'?'settings':item.to==='/whitelabel#storage'?'backup':item.to.slice(1)
const active=item=>prototypeSection(route.path)?.key===key(item)||(key(item)==='whatsapp-web'&&route.path.startsWith('/prototype/whatsapp-web'))
const checked=item=>props.visited.includes(key(item))
const navigation=computed(()=>createAppNavigation().map(item=>item.children?{...item,children:item.children.filter(child=>routeAllowed(child.to,prototypeAuth.user))}:item).filter(item=>item.separator||item.children?.length||item.to&&routeAllowed(item.to,prototypeAuth.user)))
function go(item){emit('navigate',key(item))}
</script>
<template><div class="drawer-content"><WhiteLabelBrand class="drawer-brand"/><q-list class="nav-list"><template v-for="(item,index) in navigation" :key="item.key||item.label||index"><div v-if="item.separator" class="nav-section-label">{{item.label}}</div><q-expansion-item v-else-if="item.children" v-model="expanded[item.key]" :label="item.label" :icon="item.icon" :class="item.key==='home'?'home-navigation-menu':'whatsapp-channel-menu'" :header-class="item.key==='home'?'home-navigation-heading':'whatsapp-channel-heading'"><q-item v-for="child in item.children" :key="child.to" clickable :active="active(child)" active-class="nav-item--active" class="nav-item" @click="go(child)"><q-item-section avatar><q-icon :name="child.icon"/></q-item-section><q-item-section>{{child.label}}</q-item-section><q-item-section v-if="checked(child)" side><q-icon name="check" color="teal" size="15px" aria-label="Tela visitada"/></q-item-section></q-item></q-expansion-item><q-item v-else clickable :active="active(item)" active-class="nav-item--active" :class="['nav-item',item.channelColor&&'nav-item--'+item.channelColor]" @click="go(item)"><q-item-section avatar><q-icon :name="item.icon"/></q-item-section><q-item-section>{{item.label}}</q-item-section><q-item-section v-if="checked(item)" side><q-icon name="check" color="teal" size="15px" aria-label="Tela visitada"/></q-item-section></q-item></template></q-list><div class="demo-drawer-bottom"><q-btn flat no-caps icon="north_east" label="Conhecer os planos" href="https://aitosoftwares.com/whatsapp-solucoes" target="_top"/><a data-prototype-exit href="/admin/login" target="_top">Voltar ao login</a></div></div></template>
<style scoped>
.drawer-content{display:flex;min-height:100%;flex-direction:column;padding:22px 16px 16px}.drawer-brand{margin:0 9px 25px}.nav-list{flex:1}.nav-item{min-height:46px;margin:3px 0;border-radius:14px;color:color-mix(in srgb,var(--ink) 77%,var(--app-background))}.nav-item .q-icon{color:color-mix(in srgb,var(--brand-dark) 62%,var(--muted))}.nav-item--active{background:linear-gradient(105deg,color-mix(in srgb,var(--mint) 40%,transparent),color-mix(in srgb,var(--brand) 14%,transparent));color:var(--brand-dark);font-weight:750}.nav-item--active .q-icon{color:var(--brand-dark)}.nav-section-label{padding:22px 18px 8px;color:var(--muted);font-size:11px;font-weight:750;letter-spacing:.1em;text-transform:uppercase}.home-navigation-menu :deep(.q-expansion-item__content){background:color-mix(in srgb,var(--brand) 7%,transparent);border-radius:0 0 16px 16px;padding:4px}.home-navigation-menu :deep(.q-expansion-item__content .q-item__section--avatar){min-width:38px}.home-navigation-menu :deep(.q-expansion-item__content .q-icon){font-size:20px}:deep(.home-navigation-heading .q-icon){color:var(--brand-dark)}.whatsapp-channel-menu{margin-top:8px;border-radius:16px;background:linear-gradient(125deg,#e8f9ed,#f3fcf6);border:1px solid #d3ecdb;color:#1b7150}.whatsapp-channel-menu :deep(.q-icon){color:#228258}.whatsapp-channel-menu :deep(.q-expansion-item__content){padding:2px 7px 7px}.nav-item--telegram{background:#edf7fc;color:#176d93}.nav-item--gmail{background:#fff1f0;color:#a8403e}.nav-item--telegram .q-icon{color:#269bc0}.nav-item--gmail .q-icon{color:#cf5b50}.demo-drawer-bottom{display:grid;gap:10px;margin-top:24px}.demo-drawer-bottom .q-btn{font-size:11px}.demo-drawer-bottom a{text-align:center;font-size:11px;color:var(--muted)}
</style>
